def ref(a,p):
    name=f'POSTECH - Observabilidade e Monitoramento - Aula {a}.pdf'
    first=str(p).split('–')[0].split('-')[0]
    return f'<p class="source">Fonte: <a href="{quote(name)}#page={first}">Observabilidade e Monitoramento, Aula {a}, p. {p}</a>.</p>'

def lesson(n,title,simple,technical,practice,pages,ids):
    return section('aula-'+str(n),f'Aula {n} — {title}',f'<article class="lesson"><div class="lesson-head"><span class="num">{n:02}</span><div><h3>{E(title)}</h3>'+''.join(badge(x) for x in ids)+'</div></div><dl class="facets"><div><dt>Em miúdos</dt><dd>'+simple+'</dd></div><div><dt>Entenda a técnica</dt><dd>'+technical+'</dd></div><div><dt>Prática da aula</dt><dd>'+practice+'</dd></div></dl>'+ref(n,pages)+'</article>')

def review(items):
    return ''.join('<details><summary>'+E(q)+'</summary><p>'+a+'</p></details>' for q,a in items)

# B1 — capítulo introdutório, sem inventar aulas ou comandos inexistentes.
welcome=section('visao','O que muda depois do deploy','''<div class="intro"><div class="box"><h3>Em linguagem simples</h3><p>Colocar a aplicação no ar é o começo da operação. Esta fase ensina a perceber se ela continua saudável, investigar falhas e responder antes que a equipe dependa da reclamação do cliente.</p></div><div class="box hi"><h3>Em linguagem técnica</h3><p>Logs, métricas e traces conectam instrumentação, monitoramento, diagnóstico e gestão de incidentes. O objetivo é transformar sinais do ambiente em informação e ação.</p></div></div><p class="source">Fonte: Capítulo de Projeto — Fase 4, p. 2–3. A p. 1 é capa e a p. 4 é contracapa.</p>''')
welcome+=section('trilha','A trilha de estudo em quatro blocos',table(['Bloco anunciado','O que aprender','Como se conecta'],[
('Fundamentos','Distinguir up/down de diagnóstico; logs, métricas, traces; sinais da infraestrutura, contêineres e aplicação.','Fornece vocabulário para escolher o que medir e correlacionar.'),
('Monitoramento Opensource','Prometheus, Grafana, OpenTelemetry, Jaeger, Zabbix e Grafana Alloy.','Constrói a visão central da operação e a padronização da telemetria.'),
('APM','Datadog/New Relic; alertas inteligentes, troubleshooting, desempenho e custos.','Aprofunda a investigação de transações e gargalos de código.'),
('Automação de incidentes','Práticas SRE, monitoramento ativo, escalas de plantão, escalonamento, PagerDuty/OpsGenie e Functions.','Liga detecção à resposta para reduzir tempo de recuperação.')])+ '<p class="source">Fonte: Capítulo de Projeto, p. 2–3. A introdução não fornece comandos nem configurações executáveis.</p>')
welcome+=section('glossario','Termos para começar',complement('<div class="glossary">'+''.join(f'<div class="term"><span class="k">{E(k)}</span><span class="d">{d}</span></div>' for k,d in [
('Métricas','Medidas numéricas do comportamento do ambiente ao longo do tempo.'),('Logs','Registros dos eventos que ocorreram no sistema.'),('Traces','Rastreamentos do caminho percorrido por uma requisição.'),('APM','Application Performance Monitoring: acompanhamento do desempenho das aplicações.'),('SRE','Site Reliability Engineering: práticas de engenharia voltadas à confiabilidade.'),('MTTR','No capítulo, Tempo Médio de Recuperação: indicador do tempo necessário para restaurar o serviço.'),('Call rotation','Rodízio de pessoas responsáveis pelo plantão.'),('Escalation','Encaminhamento a outro responsável ou nível de resposta quando necessário.')])+'</div>'+'<p>As definições breves são uma ponte didática. O capítulo menciona os termos (p. 2–3); as próximas aulas detalham sinais, instrumentação e operação.</p>'))
welcome+=section('fluxo','Do sinal à recuperação',complement('''<p>Fluxo de estudo derivado da proposta do capítulo; não representa uma infraestrutura já implantada.</p><ol class="flow"><li><div><strong>Emitir sinais</strong><span>A aplicação e a infraestrutura registram seu comportamento.</span></div></li><li><div><strong>Coletar e visualizar</strong><span>A equipe acompanha sinais e relaciona eventos no tempo.</span></div></li><li><div><strong>Investigar</strong><span>O trace mostra etapas da requisição; os logs acrescentam contexto; as métricas revelam tendência e impacto.</span></div></li><li><div><strong>Acionar e mitigar</strong><span>O alerta chega ao responsável e uma automação pode tentar recuperar o serviço.</span></div></li><li><div><strong>Verificar</strong><span>Novos sinais permitem avaliar se a ação teve efeito.</span></div></li></ol>'''))
welcome+=section('entrega','Ligar a trilha à entrega',f'''<p>O capítulo descreve a direção do projeto: instrumentar a aplicação, produzir alertas precisos, dashboards explicativos e automações de recuperação (p. 3). O <strong>enunciado</strong> especifica quais ferramentas e evidências são exigidas.</p>{badge('REQ-OBR-23')}{badge('SUG-01')}<div class="note"><strong>Estudo e exigência são coisas diferentes</strong>Jaeger e Zabbix fazem parte da trilha anunciada. A lista de ferramentas obrigatórias do enunciado é mais específica: Prometheus, Loki, Grafana, OTel e uma opção entre Datadog/New Relic. E-mail aparece na introdução, mas o ChatOps exigido no enunciado cita Slack, Discord ou Teams. Não substituir um entregável apenas porque outra ferramenta aparece na aula.</div><p class="source">Capítulo de Projeto, p. 2–3; enunciado, p. 3–6.</p>'''+complement('''<p>Ao estudar cada módulo, anote três coisas: o sinal que ele produz, a pergunta que ajuda a responder e a evidência que você deverá mostrar. Essa ficha evita terminar o estudo sem saber como demonstrar o aprendizado.</p>'''))
welcome+=section('leitura-critica','Como interpretar a abertura',complement('<p><strong>WEL-01 · [INCERTO]</strong>: o capítulo usa “rotas de acionamento (call rotation)” (p. 2–3). No glossário, a explicação de escala de plantão é complementar; roteamento e rodízio são conceitos relacionados, mas distintos.</p><p>O capítulo chama a atividade de Projeto Integrador; o enunciado usa Tech Challenge. “Qualquer falha” (p. 3) expressa a meta da introdução; os critérios concretos de entrega são os do enunciado. O termo Functions não determina um provedor. OTel aparece associado a tracing na introdução, mas o enunciado p. 4 exige os três sinais.</p>'))
